import type { Metadata } from "next";
import { Container } from "@/components/container";
import { ItemCard } from "@/components/item-card";
import { PageHeader, PageShell } from "@/components/page-shell";
import { projects } from "@/data/projects";

export const metadata: Metadata = {
  title: "Projects",
};

export default function ProjectsPage() {
  return (
    <PageShell>
      <PageHeader
        label="Projects"
        title="Technical work with clear systems, interfaces, and outcomes."
        description="Add projects in data/projects.ts with summaries, links, repositories, image paths, and the stack used."
      />
      <Container>
        <div className="grid gap-4 py-12 md:grid-cols-2">
          {projects.map((project) => (
            <ItemCard
              key={project.title}
              title={project.title}
              eyebrow={project.date}
              summary={project.summary}
              tags={project.tags}
            >
              <div className="space-y-5">
                {project.bullets.length ? (
                  <ul className="grid gap-2 text-sm leading-6 text-muted">
                    {project.bullets.map((bullet) => (
                      <li key={bullet} className="border-l border-line pl-3">
                        {bullet}
                      </li>
                    ))}
                  </ul>
                ) : null}
                {project.metrics.length ? (
                  <div className="flex flex-wrap gap-2">
                    {project.metrics.map((metric) => (
                      <span
                        key={`${metric.label}-${metric.value}`}
                        className="rounded-md border border-line px-2 py-1 font-mono text-xs text-muted"
                      >
                        {metric.label}: {metric.value}
                      </span>
                    ))}
                  </div>
                ) : null}
                <div className="flex flex-wrap gap-3 text-sm">
                  {project.links.map((link) => (
                    <a key={link.url} className="text-accent hover:underline" href={link.url}>
                      {link.label}
                    </a>
                  ))}
                  {project.pdfs.map((pdf) => (
                    <a key={pdf.path} className="text-accent hover:underline" href={pdf.path}>
                      {pdf.label}
                    </a>
                  ))}
                </div>
              </div>
            </ItemCard>
          ))}
        </div>
      </Container>
    </PageShell>
  );
}
